WITH src AS (
 SELECT x.*, md5('fbmn:vinhlong-old:wave03:'||x.source_key) AS dg
 FROM jsonb_to_recordset('[{"district":"Huyện Trà Ôn","name":"Nhà sách Thanh Phong","address_line":"12 đường Thống Chế Điều Bát, thị trấn Trà Ôn cũ, huyện Trà Ôn","category":"nha_sach","phone":"02703770626","tax_code":"1501062224","source_key":"dauthau:1501062224:thanhphong-traon","source_url":"https://dauthau.asia/businesslistings/detail/NHA-SACH-THANH-PHONG-189349/","verification_note":"Nguồn Viet-Biz ghi 12 đường Thống Chế Điều Bát, hồ sơ nhà thầu ghi 12/1 khu 4 cùng thị trấn; đối chiếu tên/địa điểm có khả năng cùng một cơ sở, chỉ 1 lead. Nhà thầu đã trúng gói cung cấp giấy/VPP năm 2025; chưa Sales ghé."},{"district":"Huyện Trà Ôn","name":"Nhà sách Thanh Vân","address_line":"13 Lê Lợi, thị trấn Trà Ôn cũ, huyện Trà Ôn","category":"nha_sach","phone":"02703770216","tax_code":null,"source_key":"vietbiz:thanhvan:13-leloi-traon","source_url":"https://www.viet-biz.com/nh%C3%A0-s%C3%A1ch-thanh-v%C3%A2n-0270-3770-216","verification_note":"Nguồn danh bạ có tên nhà sách nhưng phân ngành tạp hóa; cần xác minh hiện bán sách/VPP thường xuyên, chưa ghé."},{"district":"Huyện Trà Ôn","name":"Nhà sách Cô Ánh","address_line":"Số 6, tổ 19 khu phố, khu vực Vĩnh Xuân cũ, huyện Trà Ôn","category":"nha_sach","phone":"02703889474","tax_code":null,"source_key":"gmap:ChIJw22iiQxsoDERdTE0IKGLIP0","source_url":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20C%C3%B4%20%C3%81nh%20Tr%C3%A0%20%C3%94n%20V%C4%A9nh%20Xu%C3%A2n%20V%C4%A9nh%20Long&query_place_id=ChIJw22iiQxsoDERdTE0IKGLIP0","verification_note":"Nguồn danh bạ ghi Trà Ôn chung, Maps 2026 ghi Vĩnh Xuân; cần xác minh khu phố chính xác, không chuyển sang huyện khác."},{"district":"Huyện Trà Ôn","name":"Nhà sách Thầy Tám","address_line":"Khu vực xã Hựu Thành cũ, huyện Trà Ôn (Plus Code X35M+MVX)","category":"nha_sach","phone":"0939638557","tax_code":null,"source_key":"sotayvang:thaytam:x35mmvx-huuthanh","source_url":"https://sotayvang.com/nha-sach-thay-tam-huu-thanh/","verification_note":"Địa điểm ghi xã Hựu Thành 