0V%C5%A9ng%20Li%C3%AAm&query_place_id=ChIJd6R6k6oNoDERuvKM0IfgmP0","verification_note":"Nguồn Maps và Sổ Tay Vàng có cùng địa chỉ điện thoại; xã Trung Thành mới và cũ cùng tên, cần xác minh ấp."},{"district":"Huyện Vũng Liêm","name":"Văn phòng phẩm Lam Chi","address_line":"228 ĐT902, xã Quới An cũ, huyện Vũng Liêm","category":"van_phong_pham","phone":"0767932327","tax_code":null,"source_key":"gmap:ChIJWUoCX_oNoDERh58--nKS6uA","source_url":"https://www.google.com/maps/search/?api=1&query=V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20Lam%20Chi%20228%20%C4%90T902%20Qu%E1%BB%9Bi%20An%20V%C5%A9ng%20Li%C3%AAm&query_place_id=ChIJWUoCX_oNoDERh58--nKS6uA","verification_note":"Nguồn Maps mô tả bán VPP và sách giáo khoa, có photocopy; chưa Sales ghé."},{"district":"Huyện Vũng Liêm","name":"Cửa hàng Thiết bị Văn phòng Quốc Đạt","address_line":"ĐT902, khu vực huyện Vũng Liêm cũ (Plus Code 35RQ+94W)","category":"van_phong_pham","phone":"0919899448","tax_code":null,"source_key":"gmap:ChIJ_SyFKe8MoDERKdLgAHosFpQ","source_url":"https://www.google.com/maps/search/?api=1&query=Thi%E1%BA%BFt%20b%E1%BB%8B%20V%C4%83n%20ph%C3%B2ng%20Qu%E1%BB%91c%20%C4%90%E1%BA%A1t%20%C4%90T902%20V%C5%A9ng%20Li%C3%AAm&query_place_id=ChIJ_SyFKe8MoDERKdLgAHosFpQ","verification_note":"Cửa hàng thiên thiết bị văn phòng và vật tư in, chưa chắc bán dụng cụ học sinh, cần Sales xác minh nhóm hàng."},{"district":"Huyện Vũng Liêm","name":"Photocopy - VPP Phúc Hảo","address_line":"QL53, xã Hiếu Phụng cũ, huyện Vũng Liêm (Plus Code 34M9+JCJ)","category":"van_phong_pham","phone":"02703874321","tax_code":null,"source_key":"sotayvang:phuchao:34m9jcj-hieuphung","source_url":"https://sotayvang.com/cua-hang-van-phong-pham-phuc-hao-hieu-phung/","verification_note":"Cửa hàng photocopy có danh bạ VPP, Maps còn ghi 34M9+JCQ rất gần; cùng tên và số điện thoại nên GỘP một điểm."},{"district":"Huyện Vũng Liêm","name":"Shop văn phòng phẩm Phương Anh","address_line":"135 Nam Kỳ Khởi Nghĩa, khu vực thị trấn Vũng Liêm cũ","category":"van_phong_pham","phone":"0971757659","tax_code":null,"source_key":"gmap:ChIJi6gTGaANoDER4hiZKsKuspE","source_url":"https://www.google.com/maps/search/?api=1&query=Shop%20V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20Ph%C6%B0%C6%A1ng%20Anh%20135%20Nam%20K%E1%BB%B3%20Kh%E1%BB%9Fi%20Ngh%C4%A9a%20V%C5%A9ng%20Li%C3%AAm&query_place_id=ChIJi6gTGaANoDER4hiZKsKuspE","verification_note":"Cửa hàng nhỏ phân loại convenience store nhưng tên VPP; địa chỉ khác Hồng Nhan số 103; cần xác minh ngành hàng."},{"district":"Huyện Vũng Liêm","name":"Cửa hàng Văn phòng phẩm Thanh Hùng","address_line":"ĐT902, xã Quới An cũ, huyện Vũng Liêm (Plus Code 5578+52J)","category":"van_phong_pham","phone":null,"tax_code":null,"source_key":"gmap:ChIJDZs8nCkLoDERtmA-uW98zJg","source_url":"https://www.google.com/maps/search/?api=1&query=V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20Thanh%20H%C3%B9ng%20%C4%90T902%20Qu%E1%BB%9Bi%20An%20V%C5%A9ng%20Li%C3%AAm&query_place_id=ChIJDZs8nCkLoDERtmA-uW98zJg","verification_note":"Nguồn điểm bản đồ không có số nhà/số điện thoại, cần kiểm tra có cửa hàng thật và còn hoạt động."}]'::jsonb) AS x (
   district text,name text,address_line text,category text,phone text,tax_code text,
   source_key text,source_url text,verification_note text
 )
), ins AS (
 INSERT INTO public.field_prospects(
   id,area_visit_id,owner_sub,name,address_line,province,district,category,
   phone,tax_code,note,status,source_kind,research_source_key,research_source_url,research_batch
 )
 SELECT
   (substr(s.dg,1,8)||'-'||substr(s.dg,9,4)||'-5'||substr(s.dg,14,3)
     ||'-8'||substr(s.dg,18,3)||'-'||substr(s.dg,21,12))::uuid,
   NULL,'ef943de4-18f7-49ef-8340-eefb18855534',
   s.name,s.address_line,'Vĩnh Long',s.district,s.category,s.phone,s.tax_code,
   'Nguồn công khai 21/11/2026; CHƯA GHÉ; GPS chưa xác minh; hoạt động bán lẻ chưa xác minh thực địa. '
     ||s.verification_note||' Nguồn: '||s.source_url,
   'new','manual',s.source_key,s.source_url,'2026-11-21-vinh-long-old-wave-03-two-districts'
 FROM src s
 WHERE s.district IN ('Huyện Trà Ôn','Huyện Vũng Liêm')
   AND s.source_url LIKE 'https://%'
   AND NOT EXISTS (
     SELECT 1 FROM public.customers c
     WHERE c.province='Vĩnh Long' AND c.district=s.district
       AND (lower(btrim(c.name))=lower(btrim(s.name))
            OR (c.phone IS NOT NULL AND s.phone IS NOT NULL AND c.phone=s.phone))
   )
   AND NOT EXISTS (
     SELECT 1 FROM public.field_prospects p
     WHERE p.province='Vĩnh Long' AND p.district=s.district
       AND (p.research_source_key=s.source_key
            OR (lower(btrim(p.name))=lower(btrim(s.name))
                AND lower(btrim(p.address_line))=lower(btrim(s.address_line)))
            OR (p.phone IS NOT NULL AND s.phone IS NOT NULL AND p.phone=s.phone)
            OR (p.tax_code IS NOT NULL AND s.tax_code IS NOT NULL AND p.tax_code=s.tax_code))
   )
 ON CONFLICT (research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
 RETURNING district,name,category,phone,tax_code
)
SELECT district,count(*)::int AS inserted,
 count(*) FILTER(WHERE category='nha_sach')::int AS bookstores,
 count(*) FILTER(WHERE category='van_phong_pham')::int AS stationery,
 count(*) FILTER(WHERE phone IS NOT NULL)::int AS phones,
 count(*) FILTER(WHERE tax_code IS NOT NULL)::int AS tax_codes
FROM ins GROUP BY district ORDER BY district;
